/// <summary>
/// Caches whether a product is marked "Priced by Weight" to avoid repeated database lookups.
/// </summary>
public class METPricedByWeightCache
{
}

Method.Source:
/// <summary>
/// Retrieves the "Priced by weight" attribute value for a given item.
/// </summary>
/// <param name="_itemId">
/// The unique identifier of the item (Product Number) whose attribute value is being checked.
/// </param>
/// <returns>
/// A boolean value indicating whether the item is priced by weight:
/// - true  → Item is priced by weight
/// - false → Item is not priced by weight or attribute not found
/// </returns>
/// <remarks>
/// The method queries the EcoResProductAttributeValueEntity table to find the BooleanValue
/// associated with the "Priced by weight" attribute for the specified item.
/// If the attribute exists, its BooleanValue is returned; otherwise, false is returned.
/// </remarks>
public static boolean getPricedByWeightAttributeCached(ItemId _itemId)
{   
    METGetAttributeValue        getAttributeValue;
    boolean                     pricedByWeightAttributeValue;
    InventTable                 inventTable = InventTable::find(_itemId);
    EcoResProductParameters ecoResProductParameters = EcoResProductParameters::find();

    if (inventTable.RecId 
            && ecoResProductParameters.METPricedByWeight)
    {         
        getAttributeValue = METGetAttributeValue::newFromInventTable(inventTable);
        pricedByWeightAttributeValue = getAttributeValue.getAttributeValue(ecoResProductParameters.METPricedByWeight);
    }

    return  pricedByWeightAttributeValue;
}

/// <summary>
/// Gets the RecId of the EcoRes attribute used to indicate an item is "Priced by weight".
/// </summary>
/// <returns>
/// The RecId of the matching <c>EcoResAttribute</c> for the "Priced by weight" attribute.
/// </returns>
public static RecId pricedByWeightAttributeRecId()
{
    return EcoResAttribute::findByName(METConstants::PricedByWeightAttributeId,EcoResAttributeType::findByName(METConstants::EcoResAttributeTypeBoolean).RecId).RecId;
}
